	sections = {
		{
			title = "Summary",
			text = [=[Arthas Menethil was the crown prince of {link:lordaeron}Lordaeron{/link}, a knight of the Silver Hand and the student of {link:uther-the-lightbringer}Uther the Lightbringer{/link}. He was brave, beloved and proud. He set out to save his people from a plague of undeath, and he ended by destroying them. He murdered his father, King {link:terenas-menethil}Terenas Menethil{/link}, and led the {link:scourge}Scourge{/link} across the north. He now rules the undead from the frozen heart of {red:northrend}Northrend{/red}.]=],
		},
		{
			title = "Significance",
			text = [=[No fall in the history of humankind has been so great or so terrible. The name of Arthas is cursed in every land that once knew the {link:alliance}Alliance{/link}, and the lands he laid waste are still called the Plaguelands.]=],
		},
		{
			title = "The Prince",
			text = [=[Arthas was the only son of {link:terenas-menethil}Terenas{/link}. {link:uther-the-lightbringer}Uther{/link} trained him as a paladin of the {link:holy-light}Holy Light{/link}, and he was welcomed into the order of the Silver Hand. When a plague struck the northern farmlands of {link:lordaeron}Lordaeron{/link}, the king sent Arthas and Uther to end it. With {link:jaina-proudmoore}Jaina Proudmoore{/link} of {link:dalaran}Dalaran{/link} at his side, Arthas followed the sickness to the necromancer {link:kel-thuzad}Kel'Thuzad{/link} and his {link:cult-of-the-damned}Cult of the Damned{/link}, and slew him. Yet the plague spread still. At Stratholme, Arthas found that the city's grain was tainted, and that all who had eaten it would rise as undead. He ordered the city purged. Uther and Jaina refused to take part, and Arthas carried out the {link:culling-of-stratholme}Culling of Stratholme{/link} without them.]=],
		},
		{
			title = "The Fall",
			text = [=[Arthas pursued the dreadlord Mal'Ganis to Northrend. There he burned his own ships so that his men could not turn back, and he took up the cursed runeblade {red:frostmourne}Frostmourne{/red}. With it he slew Mal'Ganis, but the sword claimed his soul. He came home to {link:lordaeron}Lordaeron{/link} as a servant of the {red:lich-king}Lich King{/red}. In the throne room he murdered his father, and the kingdom fell. He destroyed the order of the Silver Hand, slew {link:uther-the-lightbringer}Uther{/link}, and raised {link:kel-thuzad}Kel'Thuzad{/link} again beside the Sunwell after laying waste to {link:quel-thalas}Quel'Thalas{/link}. He killed the ranger-general {link:sylvanas-windrunner}Sylvanas Windrunner{/link} and bound her spirit to his will.]=],
		},
		{
			title = "Deeds",
			text = [=[• He carried out the {link:culling-of-stratholme}Culling of Stratholme{/link}.
• He murdered {link:terenas-menethil}King Terenas{/link} and gave {link:lordaeron}Lordaeron{/link} to the {link:scourge}Scourge{/link}.
• He slew {link:uther-the-lightbringer}Uther the Lightbringer{/link}.
• He ravaged {link:quel-thalas}Quel'Thalas{/link} and defiled the Sunwell to raise {link:kel-thuzad}Kel'Thuzad{/link} as a lich.
• He opened the way for the {link:burning-legion}Burning Legion{/link} to {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Fate",
			text = [=[After the {link:battle-of-mount-hyjal}Battle of Mount Hyjal{/link}, the power of the Lich King waned, and Arthas lost his grip on {link:lordaeron}Lordaeron{/link}. {link:sylvanas-windrunner}Sylvanas{/link} broke free of his control, and the {link:forsaken}Forsaken{/link} rose against him. Summoned by his master, Arthas returned to Northrend. At the glacier of Icecrown he fought and defeated {link:illidan-stormrage}Illidan Stormrage{/link}. Then he climbed the Frozen Throne and put on the helm of the Lich King, and the two became one. Arthas now reigns as the Lich King in Northrend. In Lordaeron, {link:kel-thuzad}Kel'Thuzad{/link} commands the {link:scourge}Scourge{/link} in his name. {link:muradin-bronzebeard}Muradin Bronzebeard{/link}, who once followed him north, never came home.]=],
		},
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "his father, and his victim" },
		{ id = "uther-the-lightbringer", name = "Uther the Lightbringer", note = "his teacher, and his victim" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "his lost love" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "foe, then servant" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "the Lich King he joined" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "foe at Icecrown" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "his victim and enemy" },
	},
})

Add({
