	sections = {
		{
			title = "Summary",
			text = [=[Uther the Lightbringer was the first paladin of the {link:holy-light}Holy Light{/link} and the leader of the Knights of the Silver Hand. He learned his faith at the side of Archbishop {link:alonsus-faol}Alonsus Faol{/link}, fought the {link:horde}Horde{/link} across the north in the {link:second-war}Second War{/link}, and trained the prince {link:arthas-menethil}Arthas Menethil{/link}. He was the prince's teacher and friend, and he died at the prince's hand.]=],
		},
		{
			title = "Significance",
			text = [=[Uther showed the human kingdoms that faith and steel could stand together. The order he led defended {link:lordaeron}Lordaeron{/link} for a generation, and his name is still spoken with reverence by every paladin in the world.]=],
		},
		{
			title = "The Silver Hand",
			text = [=[After the {link:first-war}First War{/link}, word came north that the {link:horde}Horde{/link} had slaughtered the clerics of {link:northshire-abbey}Northshire Abbey{/link}. {link:alonsus-faol}Alonsus Faol{/link} resolved that the servants of the Light would no longer stand defenseless. With the blessing of {link:anduin-lothar}Anduin Lothar{/link}, he gathered warriors of strong faith and taught them to wield holy power in battle. Uther was the first among them. When their training was done, the archbishop named him the leader of the new Knights of the Silver Hand. Uther and his paladins, among them {link:turalyon}Turalyon{/link} and {link:tirion-fordring}Tirion Fordring{/link}, fought throughout the {link:second-war}Second War{/link} and brought healing and hope where the fighting was worst.]=],
		},
		{
			title = "The Prince",
			text = [=[In the years of peace, Uther took the young {link:arthas-menethil}Arthas{/link} as his student and welcomed him into the order. When a plague broke out in the north of {link:lordaeron}Lordaeron{/link}, King {link:terenas-menethil}Terenas Menethil{/link} sent them both to end it. At Stratholme, Arthas ordered that the city's people be slain before the plague could raise them. Uther refused. He would not strike down the living, and Arthas dismissed him from his service. The {link:culling-of-stratholme}Culling of Stratholme{/link} went on without him.]=],
		},
		{
			title = "Deeds",
			text = [=[• He was the first paladin ordained by {link:alonsus-faol}Alonsus Faol{/link} and led the Knights of the Silver Hand.
• He fought the {link:horde}Horde{/link} in the {link:second-war}Second War{/link}.
• He trained {link:arthas-menethil}Prince Arthas{/link} in the ways of the Light.
• He refused to take part in the {link:culling-of-stratholme}Culling of Stratholme{/link}.]=],
		},
		{
			title = "Fate",
			text = [=[When {link:arthas-menethil}Arthas{/link} returned from {red:northrend}Northrend{/red} and murdered his father, the prince turned on the order that had raised him. He broke the Silver Hand and hunted its knights. Uther and his last paladins guarded the urn that held the ashes of {link:terenas-menethil}King Terenas{/link}. Arthas came for it, and the student slew his teacher with the runeblade {red:frostmourne}Frostmourne{/red}. A tomb now stands in Uther's memory in the {link:western-plaguelands}Western Plaguelands{/link}, a place of grief in a dead land. Some of the paladins he trained still live, and they remember him.]=],
		},
	},
	bonds = {
