	},
	sections = {
		{
			title = "Summary",
			text = [=[Alonsus Faol was the Archbishop of the Church of the {link:holy-light}Holy Light{/link}, the spiritual father of the human kingdoms in the age of the {link:second-war}Second War{/link}. He was a short, stout old man with a white beard and a kindly face, loved by commoners and kings alike. He founded the Knights of the Silver Hand and ordained {link:uther-the-lightbringer}Uther the Lightbringer{/link} as the first of the paladins.]=],
		},
		{
			title = "Significance",
			text = [=[Before Faol, the servants of the Light healed and prayed while others fought. After him, they rode to war. The paladin orders of every human land, and the young paladins now trained at {link:northshire-abbey}Northshire Abbey{/link}, all walk the road he opened.]=],
		},
		{
			title = "The Silver Hand",
			text = [=[Faol had long served the faith, and he took the young {link:uther-the-lightbringer}Uther{/link} as his apprentice many years before the orcs came. During the {link:first-war}First War{/link}, the {link:horde}Horde{/link} burned the abbey of {link:northshire-abbey}Northshire{/link} and slaughtered its clerics. When the survivors of {link:stormwind-city}Stormwind{/link} reached {link:lordaeron}Lordaeron{/link}, the archbishop heard of the massacre, and he resolved that it would not happen again. Together with {link:anduin-lothar}Anduin Lothar{/link}, he founded an order of holy warriors. He chose knights of strong faith and taught them to call on the Light in battle. Uther, {link:turalyon}Turalyon{/link}, {link:tirion-fordring}Tirion Fordring{/link} and a few others were the first. When their training was complete, Faol named Uther the leader of the Knights of the Silver Hand.]=],
		},
		{
			title = "The Peace",
			text = [=[Faol was present when the lords of the human nations met in the capital of {link:lordaeron}Lordaeron{/link}. It is said he helped keep their tempers cool when their quarrels grew hot. After the war he turned his care to the rebuilding of the south. He sent his priests and paladins wherever they were needed, and he gave his support to the raising of the new {link:cathedral-of-light}Cathedral of Light{/link} in {link:stormwind-city}Stormwind{/link} and the restoration of {link:northshire-abbey}Northshire{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He trained {link:uther-the-lightbringer}Uther{/link} in the faith of the Light.
• He founded the Knights of the Silver Hand with {link:anduin-lothar}Anduin Lothar{/link}.
• He ordained the first paladins and named Uther their leader.
• He counselled the lords of the {link:alliance}Alliance{/link} during the {link:second-war}Second War{/link}.
• He aided the rebuilding of {link:stormwind-city}Stormwind{/link} and {link:northshire-abbey}Northshire Abbey{/link}.]=],
		},
		{
			title = "Fate",
			text = [=[Faol died in the years after the {link:second-war}Second War{/link}. The chronicles do not say how. His student {link:archbishop-benedictus}Benedictus{/link} succeeded him as archbishop, and still keeps the {link:cathedral-of-light}Cathedral of Light{/link} in {link:stormwind-city}Stormwind{/link}. Faol was laid to rest in {link:tirisfal-glades}Tirisfal Glades{/link}, in a tomb called Faol's Rest. That land now belongs to the undead, and the {link:forsaken}Forsaken{/link} walk where the faithful once came to pray.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle tells how Alonsus Faol died, or when. Nor does it record much of his life before he became archbishop.]=],
