	sections = {
		{
			title = "Summary",
			text = [=[Orgrim Doomhammer was the Warchief of the {link:horde}Horde{/link} who conquered {link:stormwind-city}Stormwind{/link} and led the orcs in the {link:second-war}Second War{/link}. He was a warrior of the {link:blackrock-clan}Blackrock clan{/link}, the bearer of the great hammer of his family, and the oldest friend of Durotan of the {link:frostwolf-clan}Frostwolves{/link}. He hated the warlocks who had corrupted his people, and he tried, in his way, to set them free. At the end of his life he found the {link:orcs}orc{/link} who would finish that work: {link:thrall}Thrall{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[Doomhammer made the {link:horde}Horde{/link} a single army with a single will. Under him it came nearer to conquering the human kingdoms than it ever had before. Yet his greatest legacy is not a conquest. It is the new Horde, and its capital of {link:orgrimmar}Orgrimmar{/link} bears his name.]=],
		},
		{
			title = "The First War",
			text = [=[In the early years of the war, Orgrim served as the second of the Warchief Blackhand, a puppet of the warlock {link:gul-dan}Gul'dan{/link}. When Durotan was murdered by Gul'dan's assassins, Orgrim's anger could no longer be contained. After the death of {link:medivh}Medivh{/link}, he challenged Blackhand to a duel to the death and crushed his skull with the Doomhammer. As Warchief, he forbade the dark magic that had poisoned Draenor. He led the {link:horde}Horde{/link} against {link:stormwind-city}Stormwind{/link} once more, and this time the city fell. He then found the lair of the warlocks' {link:shadow-council}Shadow Council{/link} and slaughtered most of them.]=],
		},
		{
			title = "The Second War",
			text = [=[Doomhammer spared {link:gul-dan}Gul'dan{/link}, who promised him new weapons. He called forth the {link:horde}Horde{/link}'s full strength and marched north. He took the {link:kingdom-of-ironforge}dwarven lands{/link} of Khaz Modan, allied with the forest trolls of the Amani, and used the red dragons of the {link:dragonmaw-clan}Dragonmaw clan{/link} in battle. His armies burned the forests of {link:quel-thalas}Quel'Thalas{/link} and laid siege to the capital of {link:lordaeron}Lordaeron{/link}. Then Gul'dan betrayed him and led away much of the Horde. The siege failed. At {link:blackrock-mountain}Blackrock Mountain{/link}, Doomhammer slew {link:anduin-lothar}Anduin Lothar{/link} in battle, but the paladin {link:turalyon}Turalyon{/link} rallied the {link:alliance}Alliance{/link}, and the Horde was crushed.]=],
		},
		{
			title = "Deeds",
			text = [=[• He slew Blackhand and made himself Warchief.
• He conquered {link:stormwind-city}Stormwind{/link} and ended the {link:first-war}First War{/link}.
• He destroyed the {link:shadow-council}Shadow Council{/link}.
• He led the {link:horde}Horde{/link} to the gates of {link:lordaeron}Lordaeron{/link}'s capital.
• He slew {link:anduin-lothar}Anduin Lothar{/link} at {link:blackrock-mountain}Blackrock Mountain{/link}.]=],
		},
		{
			title = "Fate",
			text = [=[Doomhammer was taken captive and shown in chains in the capital of {link:lordaeron}Lordaeron{/link}. He escaped and lived in hiding for many years. When the young {link:thrall}Thrall{/link}, son of Durotan, sought him out, the old warchief knew him at once. He joined Thrall in freeing the orcs of the internment camps, and he fell in one of those battles in the hills of {link:hillsbrad-foothills}Hillsbrad{/link}. Before he died, he named Thrall the new Warchief. Thrall now wears Doomhammer's black armor and carries his hammer in {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	bonds = {
