		{ id = "anduin-lothar", name = "Anduin Lothar", note = "the foe he slew" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "the king whose city he took" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "a fellow chieftain" },
	},
})

Add({
	kind = "figure",
	id = "grom-hellscream",
