	},
	sections = {
		{
			title = "Summary",
			text = [=[Grom Hellscream was the chieftain of the Warsong clan, the fiercest of the {link:orcs}orcish{/link} warlords and the truest friend of {link:thrall}Thrall{/link}. He was the first orc to drink the blood of the demon {link:mannoroth}Mannoroth{/link}, and so bound his people to the {link:burning-legion}Burning Legion{/link}. He was also the orc who broke that bond, at the cost of his own life.]=],
		},
		{
			title = "Significance",
			text = [=[The curse of the orcs began with Grom and ended with him. His death in {link:ashenvale}Ashenvale{/link} freed the orcs from the demon blood, and the {link:horde}Horde{/link} of today owes its freedom to his last stand.]=],
		},
		{
			title = "The Blood Curse",
			text = [=[On {red:draenor}Draenor{/red}, the warlock {link:gul-dan}Gul'dan{/link} gathered the chieftains of the clans and offered them a draught of {link:mannoroth}Mannoroth{/link}'s blood. Grom was the first to drink, and the others followed. The blood filled the orcs with a terrible rage and bound them to the Legion's will. When the {link:horde}Horde{/link} marched on {link:azeroth}Azeroth{/link}, Gul'dan contrived to keep Grom and his Warsong on Draenor. They missed the {link:second-war}Second War{/link} entirely. After the war, they came through the {link:dark-portal}Dark Portal{/link} and fought for it until it was destroyed, and they were left stranded in the human lands.]=],
		},
		{
			title = "The Lethargy",
			text = [=[For many years, the Warsong lived hidden in the wilds of {link:lordaeron}Lordaeron{/link}. Like all orcs, Grom was sick with the loss of the demon's fury. Yet he fought the lethargy with an iron will. When the young {link:thrall}Thrall{/link} sought him out, Grom saw in him the hope of his people. He joined Thrall in freeing the orcs from the internment camps. He was captured by the humans on the eve of the {link:third-war}Third War{/link}, and Thrall freed him again.]=],
		},
		{
			title = "Kalimdor",
			text = [=[The orcs sailed west to {link:kalimdor}Kalimdor{/link}. There the Warsong were sent into the forests of {link:ashenvale}Ashenvale{/link} to cut timber, and they came to blows with the {link:night-elves}night elves{/link}. The demigod {link:cenarius}Cenarius{/link} came to defend the forest. Desperate for victory, Grom and his warriors drank from a spring that {link:mannoroth}Mannoroth{/link} had fouled with his blood. The old curse returned. In that fury Grom slew Cenarius. {link:thrall}Thrall{/link}, aided by {link:jaina-proudmoore}Jaina Proudmoore{/link}, captured his friend and cleansed him of the rage.]=],
		},
		{
			title = "Deeds",
			text = [=[• He was the first {link:orcs}orc{/link} to drink the blood of {link:mannoroth}Mannoroth{/link}.
• He held the {link:dark-portal}Dark Portal{/link} against the {link:alliance}Alliance{/link} after the {link:second-war}Second War{/link}.
• He resisted the orcish lethargy through years of hiding.
• He helped {link:thrall}Thrall{/link} free the orcs of the camps.
• He slew {link:cenarius}Cenarius{/link}, then slew Mannoroth.]=],
		},
		{
			title = "Fate",
			text = [=[Grom and {link:thrall}Thrall{/link} went together to the canyon where {link:mannoroth}Mannoroth{/link} waited. Thrall fell to the demon's power. Grom charged alone, drove his axe into Mannoroth's breast and slew him. The demon's death freed the orcs from the blood curse. Grom died of his wounds in Thrall's arms. His clan still cuts the trees of {link:ashenvale}Ashenvale{/link} in the name of the {link:horde}Horde{/link}, and the night elves still fight them for every tree.]=],
		},
	},
