		{ id = "arthas-menethil", name = "Arthas Menethil", note = "the prince he claimed and joined" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "his servant" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "chieftain of his Horde" },
