	sections = {
		{
			title = "Summary",
			text = [=[Archimonde {link:razelikh-the-defiler}the Defiler{/link} was one of the great lords of the {link:burning-legion}Burning Legion{/link}, second only to its dark master, {link:sargeras}Sargeras{/link}. He was once a leader of the eredar, a proud people of another world, until Sargeras offered them power and he accepted. He waged the Legion's wars across countless worlds. On {link:azeroth}Azeroth{/link}, he came nearer than any demon before him to devouring the world, and he died at the foot of the World Tree.]=],
		},
		{
			title = "Significance",
			text = [=[Archimonde's invasion in the {link:third-war}Third War{/link} was the greatest demonic assault the world had known since the {link:war-of-the-ancients}War of the Ancients{/link}. His defeat at {link:mount-hyjal}Mount Hyjal{/link} forged an uneasy peace between {link:orcs}orcs{/link}, {link:humans}humans{/link} and {link:night-elves}night elves{/link}, a peace that has shaped {link:kalimdor}Kalimdor{/link} ever since.]=],
		},
		{
			title = "The Eredar",
			text = [=[Long ago, the eredar were ruled by three leaders: Archimonde, {link:kil-jaeden}Kil'jaeden{/link} and Velen. {link:sargeras}Sargeras{/link} came to them with an offer of knowledge and might. Archimonde and Kil'jaeden accepted, and they were twisted into demons. Velen refused and fled with his followers. Archimonde became one of Sargeras's greatest lieutenants. In the {link:war-of-the-ancients}War of the Ancients{/link}, ten thousand years ago, the Legion came to {link:azeroth}Azeroth{/link} through the {link:well-of-eternity}Well of Eternity{/link}. It was driven back when the Well was destroyed.]=],
		},
		{
			title = "The Third War",
			text = [=[The Legion returned many ages later. When the {link:scourge}Scourge{/link} had ravaged {link:lordaeron}Lordaeron{/link}, the lich {link:kel-thuzad}Kel'Thuzad{/link} used the spellbook of {link:medivh}Medivh{/link} to summon Archimonde into the city of {link:dalaran}Dalaran{/link}. The demon lord destroyed the city of the mages with a single blow of his power. He then led the Legion to {link:kalimdor}Kalimdor{/link}, where the {link:well-of-eternity}Well of Eternity{/link}'s last waters lay beneath the World Tree, {link:nordrassil}Nordrassil{/link}. He meant to drain its power and consume the world.]=],
		},
		{
			title = "Deeds",
			text = [=[• He accepted {link:sargeras}Sargeras{/link}'s offer and became a lord of the Legion.
• He waged war on {link:azeroth}Azeroth{/link} in the {link:war-of-the-ancients}War of the Ancients{/link}.
• He was summoned into {link:dalaran}Dalaran{/link} by {link:kel-thuzad}Kel'Thuzad{/link} and destroyed it.
• He marched on {link:mount-hyjal}Mount Hyjal{/link} to drain the power of {link:nordrassil}Nordrassil{/link}.]=],
		},
		{
			title = "Fate",
			text = [=[At the {link:battle-of-mount-hyjal}Battle of Mount Hyjal{/link}, the orcs of {link:thrall}Thrall{/link}, the men of {link:jaina-proudmoore}Jaina Proudmoore{/link} and the night elves of {link:tyrande-whisperwind}Tyrande Whisperwind{/link} and {link:malfurion-stormrage}Malfurion Stormrage{/link} held the slopes of the mountain as long as they could. Archimonde climbed at last to the World Tree. Malfurion sounded the Horn of {link:cenarius}Cenarius{/link}, and a vast host of spirits of the ancients swarmed the demon lord and destroyed him in a great blast. {link:nordrassil}Nordrassil{/link}'s power was spent, and the night elves lost their immortality. Yet the Legion's invasion was broken. Its demons still linger in the corrupted woods of {link:felwood}Felwood{/link}, and its shadow has not left the world.]=],
		},
	},
	bonds = {
