		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "foe in the Third War" },
		{ id = "queen-azshara", name = "Queen Azshara", note = "who opened the way for the Legion of old" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "slew his servant Mannoroth" },
	},
})

