	tier = "A",
	region = "kalimdor",
	allegiance = "Highborne · Naga",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Queen Azshara ruled the ancient empire of the {link:night-elves}night elves{/link} at the height of its glory. She was the most beautiful and the most powerful of her people, and they adored her. From her palace in Zin-Azshari beside the {link:well-of-eternity}Well of Eternity{/link}, she led the Highborne in the study of {link:arcane-magic}arcane magic{/link}. In her pride, she opened the world to the {link:burning-legion}Burning Legion{/link}, and her empire drowned beneath the sea.]=],
		},
		{
			title = "Significance",
			text = [=[{link:azshara}Azshara{/link}'s betrayal began the {link:war-of-the-ancients}War of the Ancients{/link} and ended in the {link:great-sundering}Great Sundering{/link}. The broken shape of {link:kalimdor}Kalimdor{/link} and the {link:eastern-kingdoms}Eastern Kingdoms{/link} is her legacy. So too, perhaps, are the {link:naga}Naga{/link} who now rise from the waves.]=],
		},
		{
			title = "The Queen of the Highborne",
			text = [=[{link:azshara}Azshara{/link}'s people named cities and mountains after her. The Highborne, the noble caste of her court, served her as priests and sorcerers. Under her rule they drew ever more deeply on the {link:well-of-eternity}Well of Eternity{/link}. Their spells reached beyond the world and caught the eye of {link:sargeras}Sargeras{/link}. The demon lord whispered to the queen, and she listened. She came to believe that the world should be cleansed of all lesser peoples, and that Sargeras would make it so.]=],
		},
		{
			title = "The War of the Ancients",
			text = [=[{link:azshara}Azshara{/link} and her Highborne opened a portal within the Well, and the demons of the Legion poured through. Her counselor Xavius served her in this work. The night elves who remained free rose against their queen, led by {link:malfurion-stormrage}Malfurion Stormrage{/link}, {link:tyrande-whisperwind}Tyrande Whisperwind{/link} and Lord Kur'talos Ravencrest. As the war raged, the Highborne worked to bring {link:sargeras}Sargeras{/link} himself into the world. They were stopped only when the Well was destroyed. Its collapse tore the land asunder, and the sea rushed in over Zin-Azshari.]=],
		},
		{
			title = "Deeds",
			text = [=[• She ruled the night elves at the height of their power.
• She led the Highborne in the use of the {link:well-of-eternity}Well of Eternity{/link}.
• She opened the way for the {link:burning-legion}Burning Legion{/link} into {link:azeroth}Azeroth{/link}.
• She sought to bring {link:sargeras}Sargeras{/link} himself into the world.]=],
		},
		{
			title = "Fate",
			text = [=[When the Well collapsed, Azshara and her Highborne vanished beneath the waves. Legends of the night elves say that they did not die, but were changed, and that the serpentine {link:naga}Naga{/link} are what they became. The naga have returned to the shores in these days, raiding the coasts of {link:kalimdor}Kalimdor{/link} and of other lands. Some of them speak of their ancient queen as if she still lives. Only the ruins of her empire remain in the land that bears her name, {link:azshara}Azshara{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No mortal record tells whether {link:azshara}Azshara{/link} still lives beneath the sea, or what she has become.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "led the rebellion against her" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "fought her court" },
		{ id = "archimonde", name = "Archimonde", note = "a lord of the Legion she served" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "led the rebellion against her" },
	},
})

Add({
	kind = "figure",
	id = "deathwing",
	title = "Deathwing",
	aliases = { "Neltharion" },
