	},
	sections = {
		{
			title = "Summary",
			text = [=[Deathwing was once Neltharion, the Earth-Warder, Aspect of the black dragonflight. He was charged with guarding the deep places of the world. Madness took him, and he betrayed the other dragonflights in the {link:war-of-the-ancients}War of the Ancients{/link}. Since then he has plotted against every people of {link:azeroth}Azeroth{/link}. His name means ruin to dragons and mortals alike.]=],
		},
		{
			title = "Significance",
			text = [=[Deathwing's treachery nearly destroyed the dragonflights. His meddling in the {link:second-war}Second War{/link} gave the {link:horde}Horde{/link} its dragons. His black brood still haunts {link:blackrock-mountain}Blackrock Mountain{/link} and other dark places of the world.]=],
		},
		{
			title = "The Earth-Warder",
			text = [=[In the ancient days, five great dragons were chosen as Aspects to guard the world. Neltharion was given dominion over the earth and its depths. Something whispered to him from deep beneath the stone, and in time his mind turned. In the {link:war-of-the-ancients}War of the Ancients{/link}, he forged a great disc of gold, the Dragon Soul. He persuaded the other Aspects to give some of their power to it, telling them it would drive back the {link:burning-legion}Burning Legion{/link}. Instead he turned it against them. The artifact's power was so great that his body began to tear apart, and plates of metal were fixed to his hide to hold him together. He fled, and the Dragon Soul was lost.]=],
		},
		{
			title = "The Second War",
			text = [=[Deathwing has long walked among mortals in human disguise, as a nobleman moving through the courts of kings. The histories say he stirred up strife wherever he could. In the {link:second-war}Second War{/link}, the Dragon Soul came into the hands of the {link:dragonmaw-clan}Dragonmaw orcs{/link}. With it, they captured {link:alexstrasza}Alexstrasza{/link}, Aspect of the red dragons, and held her beneath {link:grim-batol}Grim Batol{/link}. Her young were raised as mounts of war for the {link:horde}Horde{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He betrayed the Aspects with the Dragon Soul in the {link:war-of-the-ancients}War of the Ancients{/link}.
• He moved in secret among the courts of men.
• He let the Dragon Soul fall to the {link:dragonmaw-clan}Dragonmaw clan{/link}.
• He tried to steal the eggs of the red dragonflight from {link:grim-batol}Grim Batol{/link}.]=],
		},
		{
			title = "Fate",
			text = [=[After the {link:second-war}Second War{/link}, the Dragonmaw still held {link:alexstrasza}Alexstrasza{/link} captive in {link:grim-batol}Grim Batol{/link}. Deathwing came for her eggs, seeking to rebuild his own flight. A small band of heroes and dragons freed the red queen, and the Dragon Soul was destroyed. Deathwing was driven off in fury. Where he went, no one knows. The mountain of Grim Batol, in the {link:wetlands}Wetlands{/link}, is shunned by dwarves to this day. His children and his black dragonflight are still abroad in the world.]=],
		},
	},
	bonds = {
		{ id = "alexstrasza", name = "Alexstrasza", note = "the Aspect he helped to enslave" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "warchief of the Horde that used his gift" },
		{ id = "queen-azshara", name = "Queen Azshara", note = "ally of the Legion he claimed to fight" },
	},
})

Add({
