	allegiance = "Scourge · Cult of the Damned (formerly Kirin Tor)",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Kel'Thuzad was once an archmage of {link:dalaran}Dalaran{/link} and a member of the ruling council of the {link:kirin-tor}Kirin Tor{/link}. He turned to the forbidden art of necromancy, pledged himself to the {red:lich-king}Lich King{/red} and founded the {link:cult-of-the-damned}Cult of the Damned{/link}. He spread the plague that destroyed {link:lordaeron}Lordaeron{/link}. Slain by Prince {link:arthas-menethil}Arthas Menethil{/link}, he rose again as a lich. He now commands the {link:scourge}Scourge{/link} in Lordaeron in his master's name.]=],
		},
		{
			title = "Significance",
			text = [=[Without Kel'Thuzad, the plague of undeath might never have reached the people of {link:lordaeron}Lordaeron{/link}. He was the Lich King's voice among the living, and he opened the way for the {link:burning-legion}Burning Legion{/link} to return to {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "The Archmage",
			text = [=[Kel'Thuzad was one of the greatest mages of {link:dalaran}Dalaran{/link}, but he believed his fellow magi were too timid in their studies. He began to delve into the dark art of necromancy. When the council forbade it, he did not stop. A voice called to him from {red:northrend}Northrend{/red}. He answered it, travelled to the frozen north and swore himself to the Lich King. His master promised him eternal life.]=],
		},
		{
			title = "The Cult of the Damned",
			text = [=[Kel'Thuzad returned to {link:lordaeron}Lordaeron{/link} and spoke to the poor and the weary of a new society where all would be equal and none would die. Thousands joined his {link:cult-of-the-damned}Cult of the Damned{/link}. Through them, he tainted the grain of the northern granaries with a plague that turned the living to undead. When {link:arthas-menethil}Arthas{/link} came north to fight the plague, he found Kel'Thuzad at {link:ruins-of-andorhal}Andorhal{/link} and slew him. Yet the necromancer's spirit remained, and it whispered to the prince as he fell.]=],
		},
		{
			title = "Deeds",
			text = [=[• He studied necromancy in defiance of the {link:kirin-tor}Kirin Tor{/link}.
• He swore himself to the Lich King in Northrend.
• He founded the {link:cult-of-the-damned}Cult of the Damned{/link}.
• He spread the plague of undeath through {link:lordaeron}Lordaeron{/link}'s grain.
• He summoned {link:archimonde}Archimonde{/link} into {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Fate",
			text = [=[When {link:arthas-menethil}Arthas{/link} became a servant of the Lich King, he carried the necromancer's remains to {link:quel-thalas}Quel'Thalas{/link}. There, in the waters of the Sunwell, Kel'Thuzad was reborn as a lich. With the spellbook of {link:medivh}Medivh{/link}, he summoned {link:archimonde}Archimonde{/link} into {link:dalaran}Dalaran{/link}, and the demon lord laid the city in ruins. When Arthas returned to Northrend, Kel'Thuzad stayed behind to rule the {link:scourge}Scourge{/link} in {link:lordaeron}Lordaeron{/link}. He does so still. The great necropolis of {red:naxxramas}Naxxramas{/red} floats above the Plaguelands, and his cultists keep their school of dark learning in the old castle of {link:caer-darrow}Caer Darrow{/link}.]=],
		},
	},
	bonds = {
