		{ id = "ner-zhul", name = "Ner'zhul", note = "the Lich King he swore to" },
		{ id = "archimonde", name = "Archimonde", note = "the demon he summoned" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "whose ashes made room for his bones" },
	},
})

Add({
