	},
	hint = [=[Seek the lady of Theramore in the tower of her island citadel.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Lady Jaina Proudmoore rules {link:theramore-isle}Theramore{/link}, the island stronghold of the {link:alliance}Alliance{/link} on the eastern shore of {link:kalimdor}Kalimdor{/link}. She is the daughter of the Lord Admiral {link:daelin-proudmoore}Daelin Proudmoore{/link} of {link:kul-tiras}Kul Tiras{/link} and a sorceress trained in {link:dalaran}Dalaran{/link} by the {link:kirin-tor}Kirin Tor{/link}. She walked beside Prince {link:arthas-menethil}Arthas Menethil{/link} in the days of the plague, and she parted from him before his fall. She led the survivors of the north across the sea, and she made a peace with the {link:horde}Horde{/link} that no one before her had thought possible.]=],
		},
		{
			title = "Significance",
			text = [=[Jaina is the bridge between the old enemies. She stood with {link:thrall}Thrall{/link} at the {link:battle-of-mount-hyjal}Battle of Mount Hyjal{/link}, and she keeps faith with him still. That peace cost her her father. It is fragile, and many on both sides would see it broken.]=],
		},
		{
			title = "The Plague",
			text = [=[As a young woman, Jaina studied magic in {link:dalaran}Dalaran{/link} under the archmage Antonidas, and she showed rare gifts. When a strange plague spread through the northern farmlands of {link:lordaeron}Lordaeron{/link}, she went with {link:arthas-menethil}Prince Arthas{/link} to find its source. Together they uncovered the {link:cult-of-the-damned}Cult of the Damned{/link} and the tainted grain. At Stratholme, Arthas ordered the city's people slain before they could rise as undead. Jaina would not take part, and she left him there. The {link:culling-of-stratholme}Culling of Stratholme{/link} went on without her.]=],
		},
		{
			title = "The Journey West",
			text = [=[A mysterious prophet urged the leaders of the east to sail west across the sea. Jaina heeded him when others did not, and she led the survivors of {link:lordaeron}Lordaeron{/link} to {link:kalimdor}Kalimdor{/link}. There she met {link:thrall}Thrall{/link} and his orcs, the old enemies of her people. The prophet brought them together against a greater foe, and at {link:mount-hyjal}Mount Hyjal{/link} human, {link:orcs}orc{/link} and {link:night-elves}night elf{/link} fought side by side until {link:archimonde}Archimonde{/link} was destroyed.]=],
		},
		{
			title = "Deeds",
			text = [=[• She studied magic among the {link:kirin-tor}Kirin Tor{/link} of {link:dalaran}Dalaran{/link}.
• She hunted the plague with {link:arthas-menethil}Arthas{/link} and refused the {link:culling-of-stratholme}Culling of Stratholme{/link}.
• She led the survivors of {link:lordaeron}Lordaeron{/link} west to {link:kalimdor}Kalimdor{/link}.
• She fought beside {link:thrall}Thrall{/link} and the night elves at {link:mount-hyjal}Mount Hyjal{/link}.
• She founded {link:theramore-isle}Theramore{/link} and made peace with the {link:horde}Horde{/link}.]=],
		},
		{
			title = "Theramore",
			text = [=[After the war, Jaina raised {link:theramore-isle}Theramore{/link} on an isle off the coast of {link:dustwallow-marsh}Dustwallow Marsh{/link}. Then her father came to {link:kalimdor}Kalimdor{/link} with a great fleet. {link:daelin-proudmoore}Daelin{/link} would not accept a peace with the orcs, and he made war on them. Jaina could not persuade him to stop. She would not let him destroy the peace, and she stood aside while the {link:horde}Horde{/link} defended itself. Daelin was slain in the fighting before the walls of Theramore. His daughter grieves, and the sailors who followed him have not forgiven her.]=],
		},
		{
			title = "The Present Day",
			text = [=[Jaina rules {link:theramore-isle}Theramore{/link} from its citadel. The city is a haven for the people of the lost north, and a gate for the {link:alliance}Alliance{/link} into {link:kalimdor}Kalimdor{/link}. She keeps the peace with {link:thrall}Thrall{/link} as best she can, while the soldiers of both sides clash in the wilds.]=],
		},
	},
	chapters = {
		{
			key = "the-missing-diplomat",
			title = "The Missing Diplomat",
			hint = "Follow the trail of the missing diplomat to Theramore.",
			unlock = {
				{ type = "quest", id = 1324 },
				{ type = "quest", id = 1267 },
			},
			text = [=[The trail of a stolen envoy led from {link:stormwind-city}Stormwind{/link} to {link:menethil-harbor}Menethil Harbor{/link}, and from there across the sea to {link:dustwallow-marsh}Dustwallow Marsh{/link}. At its end stood {link:private-hendel}Private Hendel{/link}, a soldier of {link:theramore-isle}Theramore{/link} who had sold himself to the {link:defias-brotherhood}Defias Brotherhood{/link}. When he was unmasked, he drew his blade. Jaina and her guards came to take him alive, for a dead traitor tells nothing. The lady of Theramore gave her quiet thanks to those who had brought the truth to light. She could not thank them openly. What Hendel knows of the missing king of Stormwind is a matter for her questioners.]=],
