Add({
	kind = "figure",
	id = "khadgar",
	title = "Khadgar",
	subtitle = "Apprentice of the Last Guardian",
	tier = "A",
	region = "eastern-kingdoms",
	allegiance = "Kirin Tor · Alliance of Lordaeron",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Khadgar was a young mage of {link:dalaran}Dalaran{/link} sent by the {link:kirin-tor}Kirin Tor{/link} to serve as apprentice to {link:medivh}Medivh{/link}, the last Guardian of {link:tirisfal-glades}Tirisfal{/link}. He was the first to see that the Guardian himself had brought the orcs to {link:azeroth}Azeroth{/link}. He fought in the {link:first-war}First War{/link} and the {link:second-war}Second War{/link}, and he became one of the great archmagi of his age. He passed through the {link:dark-portal}Dark Portal{/link} long ago, and he has not returned.]=],
		},
		{
			title = "Significance",
			text = [=[Khadgar carried the truth out of {link:karazhan}Karazhan{/link}. Without him, {link:stormwind-city}Stormwind{/link} might never have known who its true enemy was. In the {link:second-war}Second War{/link} he stood beside {link:anduin-lothar}Anduin Lothar{/link} as a leader of the {link:alliance}Alliance{/link}, and in the end he closed the way between the worlds at the cost of his own return.]=],
		},
		{
			title = "Karazhan",
			text = [=[The magi of {link:dalaran}Dalaran{/link} had long wished to learn the secrets of {link:karazhan}Medivh's tower{/link}. They sent Khadgar as his apprentice, and they bade him watch. The Guardian took him in and taught him. Khadgar soon learned that his master held long silences, strange visions and a darkness he would not speak of. With the half-{link:orcs}orc{/link} {link:garona}Garona{/link}, who came to the tower as an envoy of the {link:horde}Horde{/link}, he discovered that {link:medivh}Medivh{/link} himself had opened the {link:dark-portal}Dark Portal{/link}. The two of them carried the warning to King {link:llane-wrynn}Llane Wrynn{/link}. Then Khadgar climbed Karazhan with {link:anduin-lothar}Lothar{/link} to face his master. Medivh was slain. In that battle the young mage aged many years in a moment, and he came down from the tower with the face of an old man.]=],
		},
		{
			title = "The Second War",
			text = [=[Khadgar went north with {link:anduin-lothar}Lothar{/link} and the exiles of {link:stormwind-city}Stormwind{/link}. In {link:lordaeron}Lordaeron{/link} he was one of the champion's lieutenants, together with the paladin {link:turalyon}Turalyon{/link}. He fought the {link:horde}Horde{/link} across the northern kingdoms and helped bring about its defeat at {link:blackrock-mountain}Blackrock Mountain{/link}. When the war was won, the {link:alliance}Alliance{/link} destroyed the {link:dark-portal}Dark Portal{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He served as the last apprentice of {link:medivh}Medivh{/link} in {link:karazhan}Karazhan{/link}.
• He uncovered Medivh's part in the coming of the orcs and warned {link:llane-wrynn}King Llane{/link}.
• He fought beside {link:anduin-lothar}Anduin Lothar{/link} when Medivh was slain.
• He served as a lieutenant of the {link:alliance}Alliance{/link} in the {link:second-war}Second War{/link}.
• He led the Alliance beyond the {link:dark-portal}Dark Portal{/link} after the war.]=],
		},
		{
			title = "Beyond the Portal",
			text = [=[Some years after the {link:second-war}Second War{/link}, the Portal opened once more. {link:orcs}Orcs{/link} came through it from {red:draenor}Draenor{/red} to steal relics of power, sent by the old shaman {link:ner-zhul}Ner'zhul{/link}. The {link:alliance}Alliance{/link} sent an army after them into the orcs' homeworld. Khadgar led it with {link:turalyon}Turalyon{/link}. Ner'zhul's spells tore Draenor apart. To keep the ruin from spilling into {link:azeroth}Azeroth{/link}, the Alliance's leaders chose to close the Portal from the far side. They knew that they could not come home. The Portal fell silent, and the expedition was lost to its people.]=],
		},
		{
			title = "Fate",
			text = [=[No word of Khadgar has reached the kingdoms since the Portal was closed. In the {link:blasted-lands}Blasted Lands{/link}, the magi of the {link:kirin-tor}Kirin Tor{/link} keep watch over the ruined gate from the fortress of {link:nethergarde-keep}Nethergarde{/link}, and they have not forgotten him.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle of the kingdoms tells what became of Khadgar and his companions beyond the Portal.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "his master" },
		{ id = "garona", name = "Garona", note = "his ally in Karazhan" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "his commander" },
		{ id = "turalyon", name = "Turalyon", note = "his companion in two wars" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "his foe beyond the Portal" },
	},
})

