	tier = "A",
	region = "eastern-kingdoms",
	allegiance = "Knights of the Silver Hand · Alliance of Lordaeron",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Turalyon was a young priest of the {link:holy-light}Holy Light{/link} who became one of the first paladins of the Knights of the Silver Hand. He served as a lieutenant of {link:anduin-lothar}Anduin Lothar{/link} in the {link:second-war}Second War{/link}. When Lothar fell, Turalyon took up his command and won the war. Afterwards he led the {link:alliance}Alliance{/link} beyond the {link:dark-portal}Dark Portal{/link}, and he did not return.]=],
		},
		{
			title = "Significance",
			text = [=[It was Turalyon who turned the {link:alliance}Alliance{/link}'s darkest hour into victory. His charge at {link:blackrock-mountain}Blackrock Mountain{/link} broke the old {link:horde}Horde{/link}, and the peace that the northern kingdoms knew for a generation was his gift.]=],
		},
		{
			title = "The Silver Hand",
			text = [=[Turalyon was a priest of the church in {link:lordaeron}Lordaeron{/link} when the exiles of {link:stormwind-city}Stormwind{/link} came north. {link:anduin-lothar}Lothar{/link} saw strength in him and made him one of his lieutenants, with the mage {link:khadgar}Khadgar{/link}. Turalyon doubted himself and his faith. Yet he was among the first knights whom Archbishop {link:alonsus-faol}Alonsus Faol{/link} trained to wield the Light in battle, with {link:uther-the-lightbringer}Uther the Lightbringer{/link}, {link:tirion-fordring}Tirion Fordring{/link} and a few others. He led the {link:alliance}Alliance{/link}'s armies against the {link:horde}Horde{/link} in the north, and he learned to trust the power he had been given.]=],
		},
		{
			title = "Blackrock Mountain",
			text = [=[At the end of the war, the {link:alliance}Alliance{/link} drove the {link:horde}Horde{/link} south to {link:blackrock-mountain}Blackrock Mountain{/link}. In the battle at the mountain's foot, the warchief {link:orgrim-doomhammer}Orgrim Doomhammer{/link} slew {link:anduin-lothar}Lothar{/link}. The soldiers of the Alliance wavered. Turalyon took up his commander's sword and rallied them. The paladins called upon the Light, and the Horde was broken. Doomhammer was taken captive. Turalyon pursued the last orcs to the {link:dark-portal}Dark Portal{/link}, and the Alliance destroyed the gate.]=],
		},
		{
			title = "Deeds",
			text = [=[• He was among the first paladins of the Silver Hand.
• He served as {link:anduin-lothar}Anduin Lothar{/link}'s lieutenant in the {link:second-war}Second War{/link}.
• He rallied the {link:alliance}Alliance{/link} after Lothar's death and won the battle at {link:blackrock-mountain}Blackrock Mountain{/link}.
• He drove the {link:horde}Horde{/link} to the {link:dark-portal}Dark Portal{/link} and saw it destroyed.
• He led the Alliance's army into {red:draenor}Draenor{/red} with {link:khadgar}Khadgar{/link}.]=],
		},
		{
			title = "Beyond the Portal",
			text = [=[Some years later, the Portal opened again, and orcs came through to steal relics of power for the shaman {link:ner-zhul}Ner'zhul{/link}. Turalyon led the {link:alliance}Alliance{/link}'s army into Draenor with {link:khadgar}Khadgar{/link}. With them went the ranger Alleria Windrunner, elder sister of {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, and other heroes of the war. The expedition fought the orcs across their broken world. When Ner'zhul's spells began to tear Draenor apart, its leaders closed the Portal from the far side so that the ruin would not reach {link:azeroth}Azeroth{/link}. They could not come home.]=],
		},
		{
			title = "Fate",
			text = [=[Turalyon has not been seen in the kingdoms since the Portal was closed. The paladins of the north still speak his name beside {link:uther-the-lightbringer}Uther{/link}'s.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle of the kingdoms records what became of Turalyon beyond the Portal.]=],
		},
	},
	bonds = {
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "his commander" },
		{ id = "khadgar", name = "Khadgar", note = "his companion in two wars" },
		{ id = "uther-the-lightbringer", name = "Uther the Lightbringer", note = "a brother of the Silver Hand" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "the warchief he defeated" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "ordained him" },
	},
})

Add({
	kind = "figure",
