	pin = { x = 7.6, y = 43.7 },
	unlock = {
		{ type = "interact" },
		{ type = "read" },
	},
	hint = [=[Seek the hermit who fishes by a hut on the western edge of the Eastern Plaguelands.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Tirion Fordring was once the lord of Mardenholde Keep and one of the first paladins of the Silver Hand. He was stripped of his lands and titles for defending an {link:orcs}orc{/link}, and driven into exile. He now lives alone in a hut in the {link:eastern-plaguelands}Eastern Plaguelands{/link}, an old man in a land of the dead. His son leads the {link:scarlet-crusade}Scarlet Crusade{/link} at {link:hearthglen}Hearthglen{/link}, and believes that his father is long dead.]=],
		},
		{
			title = "Significance",
			text = [=[Tirion is a man of the Light who kept his honor when his order and his kingdom would not. Few in {link:lordaeron}Lordaeron{/link} remember him. Yet the orcs who know his tale honor him, and the story of his fall speaks to anyone who has had to choose between the law and what is right.]=],
		},
		{
			title = "The Silver Hand",
			text = [=[Tirion was among the first knights trained by Archbishop {link:alonsus-faol}Alonsus Faol{/link}, with {link:uther-the-lightbringer}Uther the Lightbringer{/link} and {link:turalyon}Turalyon{/link}. He fought the {link:horde}Horde{/link} in the {link:second-war}Second War{/link}. After the war he ruled the lands of {link:hearthglen}Hearthglen{/link} from Mardenholde Keep with his wife, Karandra, and his son, {link:taelan-fordring}Taelan{/link}.]=],
		},
		{
			title = "The Trial",
			text = [=[One day Tirion came upon an old {link:orcs}orc{/link} warrior hiding in the ruins near his lands. It was {link:eitrigg}Eitrigg{/link}. The orc could have killed him, and he spared him instead. Tirion saw honor in him and let him go. When his own soldiers came to kill the orc, Tirion defended him. For that, he was tried for treason. He was stripped of his lands and titles and banished from the order. His wife told their son that he had died, and {link:taelan-fordring}Taelan{/link} was taken to his father's false grave.]=],
		},
		{
			title = "Deeds",
			text = [=[• He was among the first paladins of the Knights of the Silver Hand.
• He fought the {link:horde}Horde{/link} in the {link:second-war}Second War{/link}.
• He ruled Mardenholde Keep and the lands around {link:hearthglen}Hearthglen{/link}.
• He spared the {link:orcs}orc{/link} {link:eitrigg}Eitrigg{/link} and defended him against his own men.]=],
		},
		{
			title = "The Present Day",
			text = [=[Tirion lives alone by the river, far from any road. His son {link:taelan-fordring}Taelan{/link} grew up to be a paladin and is now Highlord of the {link:scarlet-crusade}Scarlet Crusade{/link} at {link:hearthglen}Hearthglen{/link}, bound to an order that has lost its way. {link:eitrigg}Eitrigg{/link} serves {link:thrall}Thrall{/link} in {link:orgrimmar}Orgrimmar{/link} and has not forgotten the man who saved him.]=],
		},
	},
	chapters = {
		{
			key = "redemption",
			title = "Redemption",
			hint = "Sit with the old man by the river and hear his tale.",
			unlock = {
				{ type = "quest", id = 5742 },
			},
			text = [=[Tirion asked only that his guest sit down and listen. He told of his fall and of his son, who had grown up without him. He did not ask for his own name to be cleared. He asked for {link:taelan-fordring}Taelan{/link} to be saved from what the Crusade had made of him.]=],
		},
		{
			key = "of-forgotten-memories",
			title = "Of Forgotten Memories",
			hint = [=[Recover a toy from a false grave in the south of the Plaguelands.]=],
			unlock = {
				{ type = "quest", id = 5781 },
			},
			text = [=[When {link:taelan-fordring}Taelan{/link} was seven, his father gave him a small war hammer, a copy of his own. After Tirion's banishment, the boy buried it at his father's false grave in the {link:the-undercroft}Undercroft{/link}. It had lain there ever since, and Tirion asked for it back.]=],
		},
		{
			key = "of-lost-honor",
			title = "Of Lost Honor",
			hint = "Recover what Taelan threw down at Northdale.",
			unlock = {
				{ type = "quest", id = 5845 },
			},
			text = [=[When {link:uther-the-lightbringer}Uther{/link} fell and the Silver Hand was destroyed, the young {link:taelan-fordring}Taelan{/link} fought on as long as he could. At the hamlet of {link:northdale}Northdale{/link} he made a last stand, and there he cast the order's banner to the ground and turned his back on it. Tirion looked on the torn banner and remembered the day he swore his own oath.]=],
		},
		{
			key = "in-dreams",
			title = "In Dreams",
			hint = "Bring Taelan to his father.",
			unlock = {
				{ type = "quest", id = 5944 },
			},
			text = [=[{link:taelan-fordring}Taelan{/link} had dreamed of his father for years. Remembering what he had been, he left {link:hearthglen}Hearthglen{/link} to find him. The Crusade hunted him down on the road, and the Grand Inquisitor Isillien slew him in front of his father. In his grief Tirion declared that the order he had served was not dead. He named himself Highlord of a new Silver Hand, reborn from the old.]=],
		},
	},
	mentions = {
		{
			text = "Redemption",
			unlock = {
				{ type = "quest", id = 5742 },
			},
		},
		{
			text = "Of Forgotten Memories",
			unlock = {
				{ type = "quest", id = 5781 },
			},
		},
		{
			text = "Of Lost Honor",
			unlock = {
				{ type = "quest", id = 5845 },
			},
		},
		{
			text = "Of Love and Family",
			unlock = {
				{ type = "quest", id = 5848 },
			},
		},
		{
			text = "In Dreams",
			unlock = {
				{ type = "quest", id = 5944 },
			},
		},
	},
	bonds = {
		{ id = "eitrigg", name = "Eitrigg", note = "the orc he spared" },
		{ id = "uther-the-lightbringer", name = "Uther the Lightbringer", note = "a brother of the Silver Hand" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "his teacher in the Light" },
		{ id = "turalyon", name = "Turalyon", note = "a brother of the Silver Hand" },
