})

Add({
	kind = "figure",
	id = "garona",
	title = "Garona",
	subtitle = "The Half-Orc",
	tier = "B",
	region = "eastern-kingdoms",
	allegiance = "Unknown (formerly the Shadow Council)",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Garona was a half-{link:orcs}orc{/link} of mixed blood, a spy and an envoy of the {link:horde}Horde{/link} in the {link:first-war}First War{/link}. The warlock {link:gul-dan}Gul'dan{/link} sent her to the tower of {link:medivh}Medivh{/link}. There she befriended the young mage {link:khadgar}Khadgar{/link}, and she came to serve King {link:llane-wrynn}Llane Wrynn{/link} of {link:stormwind-city}Stormwind{/link}. She also murdered him.]=],
		},
		{
			title = "Significance",
			text = [=[Garona helped bring the truth of {link:medivh}Medivh{/link}'s treachery to {link:stormwind-city}Stormwind{/link}, and she struck the blow that ended its king. Both deeds were hers, and neither was fully her own.]=],
		},
		{
			title = "Envoy and Spy",
			text = [=[Garona was despised among the orcs for her mixed blood, and she learned early to survive by her wits. The {link:shadow-council}Shadow Council{/link} of {link:gul-dan}Gul'dan{/link} made use of her. She came to {link:karazhan}Karazhan{/link} as the {link:horde}Horde{/link}'s envoy to the Guardian. There she and {link:khadgar}Khadgar{/link} learned that {link:medivh}Medivh{/link} himself had brought the orcs to {link:azeroth}Azeroth{/link}. She stood with Khadgar and {link:anduin-lothar}Anduin Lothar{/link} when the Guardian was slain. Afterwards she took service in {link:stormwind-city}Stormwind{/link} and became a trusted adviser to the king.]=],
		},
		{
			title = "Deeds",
			text = [=[• She served as the {link:horde}Horde{/link}'s envoy to {link:medivh}Medivh{/link} in {link:karazhan}Karazhan{/link}.
• She helped {link:khadgar}Khadgar{/link} uncover Medivh's betrayal.
• She was present at the Guardian's death.
• She slew {link:llane-wrynn}King Llane{/link} Wrynn in his own keep.]=],
		},
		{
			title = "Fate",
			text = [=[Garona's mind was not her own. The warlocks of the {link:shadow-council}Shadow Council{/link} held a hidden power over her will. When {link:orgrim-doomhammer}Orgrim Doomhammer{/link} besieged {link:stormwind-city}Stormwind{/link} for the last time, she killed {link:llane-wrynn}Llane{/link} in his chamber, and the young prince {link:varian-wrynn}Varian Wrynn{/link} saw it. Then she fled. No one in the kingdoms knows where she went.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Where Garona has gone since the fall of {link:stormwind-city}Stormwind{/link}, and whether she still lives, the chronicles do not say.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "her king, and her victim" },
		{ id = "khadgar", name = "Khadgar", note = "her friend in Karazhan" },
		{ id = "medivh", name = "Medivh", note = "the Guardian she served as envoy" },
		{ id = "gul-dan", name = "Gul'dan", note = "her master" },
	},
})

Add({
	kind = "figure",
	id = "alexstrasza",
	title = "Alexstrasza",
	aliases = { "Alexstrasza the Life-Binder" },
	subtitle = "Queen of the Red Dragons",
	tier = "A",
	region = "eastern-kingdoms",
	allegiance = "Red dragonflight",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Alexstrasza is the Aspect of the red dragonflight, the Dragonqueen, keeper of life. In the ancient days she was given power over all living things by the makers of the world. She has watched over {link:azeroth}Azeroth{/link} since before the elves built their first cities. In the years of the {link:second-war}Second War{/link} she was a prisoner of the orcs, and her children were made into weapons of war.]=],
		},
		{
			title = "Significance",
			text = [=[No mortal race has suffered more from the betrayal of {link:deathwing}Deathwing{/link} than the red dragons. Their captivity at {link:grim-batol}Grim Batol{/link} gave the {link:horde}Horde{/link} its dragons, and it is still the cause of the hatred between the red flight and the orcs of the {link:dragonmaw-clan}Dragonmaw Clan{/link}.]=],
		},
		{
			title = "The Aspects",
			text = [=[In the ancient days, five great dragons were chosen to guard the world. Alexstrasza, greatest of them, was made the guardian of all life. {link:deathwing}Neltharion{/link} the Earth-Warder was her fellow. In the {link:war-of-the-ancients}War of the Ancients{/link}, he persuaded the Aspects to give part of their power to his great disc of gold, the Dragon Soul, and then turned it against them. The dragons were scattered and the red flight suffered terribly. Alexstrasza never forgot it.]=],
		},
		{
			title = "Grim Batol",
			text = [=[In the {link:second-war}Second War{/link}, the Dragon Soul came into the hands of the orcs of the Dragonmaw. With its power they seized Alexstrasza and bound her beneath the mountain of {link:grim-batol}Grim Batol{/link} in the {link:wetlands}Wetlands{/link}. They took her eggs as they were laid, and they raised her young as mounts of war. The red dragons flew for the {link:horde}Horde{/link} against the {link:alliance}Alliance{/link}, burning the forests of {link:quel-thalas}Quel'Thalas{/link} and the towns of the north.]=],
		},
		{
			title = "Deeds",
			text = [=[• She was chosen as the Aspect of life in the ancient days.
• She was betrayed by {link:deathwing}Neltharion{/link} in the {link:war-of-the-ancients}War of the Ancients{/link}.
• She was held captive by the Dragonmaw at {link:grim-batol}Grim Batol{/link}.
• She was freed, and she saw the Dragon Soul destroyed.]=],
		},
		{
			title = "The Present Day",
			text = [=[Long after the war, the Dragonmaw still held the queen. {link:deathwing}Deathwing{/link} came to {link:grim-batol}Grim Batol{/link} for her eggs, meaning to take her children for his own. A small band of heroes and dragons freed Alexstrasza. The Dragon Soul was destroyed, and her power returned. The red dragons turned upon their captors and drove Deathwing off. The Dragonmaw still cling to the {link:wetlands}Wetlands{/link}, and the red dragons still hunt them. Where the Dragonqueen herself now dwells, few mortals know.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The chronicles of the kingdoms say little of where the Dragonqueen has gone since her freedom.]=],
		},
	},
	bonds = {
		{ id = "deathwing", name = "Deathwing", note = "her fellow Aspect, and her betrayer" },
		{ id = "queen-azshara", name = "Queen Azshara", note = "whose war saw the Aspects betrayed" },
	},
})

Add({
	kind = "figure",
	id = "cenarius",
	title = "Cenarius",
	subtitle = "Lord of the Forest",
	tier = "A",
	region = "kalimdor",
	allegiance = "The forests of Kalimdor · Cenarion Circle",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Cenarius was a demigod of the wild, the lord of the forests of {link:kalimdor}Kalimdor{/link}. The {link:night-elves}night elves{/link} held him to be a child of their moon goddess, Elune. He was the teacher of {link:malfurion-stormrage}Malfurion Stormrage{/link} and the father of the druidic arts among mortals. He fell in the {link:third-war}Third War{/link}, slain by {link:grom-hellscream}Grom Hellscream{/link} in the woods of {link:ashenvale}Ashenvale{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[Every druid who walks the world walks a path that Cenarius opened. The {link:cenarion-circle}Cenarion Circle{/link}, which gathers {link:night-elves}night elf{/link} and {link:tauren}tauren{/link} druids together, bears his name. His death was a wound to the forests of {link:kalimdor}Kalimdor{/link}, and the night elves have not forgiven it.]=],
		},
		{
			title = "The First Druid",
			text = [=[In the age before the {link:war-of-the-ancients}War of the Ancients{/link}, Cenarius dwelt in the groves of {link:mount-hyjal}Mount Hyjal{/link}. He took the young {link:malfurion-stormrage}Malfurion{/link} as his student and taught him to shape the powers of nature. When the {link:burning-legion}Burning Legion{/link} came through the {link:well-of-eternity}Well of Eternity{/link}, Cenarius led the ancient spirits of the forest into battle alongside the night elves. After the {link:great-sundering}Great Sundering{/link}, the druids of Malfurion's order took up his teachings and kept them for ten thousand years. His name lived on in the Horn of Cenarius, which Malfurion would one day sound at the foot of the World Tree.]=],
		},
		{
			title = "His Children",
			text = [=[Cenarius had many children. The dryads and the keepers of the grove are said to be his. His son Zaetar was the father of the first centaurs, a race that now remembers little of him but his wrath. His son {link:keeper-remulos}Remulos{/link} keeps the sacred glade of {link:moonglade}Moonglade{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He taught {link:malfurion-stormrage}Malfurion{/link} and the first druids the ways of nature.
• He led the spirits of the forest in the {link:war-of-the-ancients}War of the Ancients{/link}.
• He watched over the forests of {link:kalimdor}Kalimdor{/link} for ten thousand years.
• He fought the orcs who came to cut the trees of {link:ashenvale}Ashenvale{/link}.
• The horn that bears his name summoned the spirits of the ancients against {link:archimonde}Archimonde{/link} at the {link:battle-of-mount-hyjal}Battle of Mount Hyjal{/link}.]=],
		},
		{
			title = "Fate",
			text = [=[In the {link:third-war}Third War{/link} the orcs of the Warsong clan came to {link:ashenvale}Ashenvale{/link} to cut timber. The night elves fought them, and Cenarius came to defend his forest. The orcs could not stand against him. In their despair, {link:grom-hellscream}Grom Hellscream{/link} and his warriors drank from a spring fouled by the blood of {link:mannoroth}Mannoroth{/link}, and the old rage came upon them. In that fury they slew the demigod. Cenarius is dead. His druids still honor him, and his children still guard his groves.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Whether any power of Cenarius survived his death, the chronicles do not say.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "his student" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "his slayer" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "brother of his student" },
		{ id = "mannoroth", name = "Mannoroth", note = "whose blood maddened his slayers" },
	},
})

Add({
	kind = "figure",
	id = "kil-jaeden",
	title = "Kil'jaeden",
	aliases = { "Kil'jaeden the Deceiver" },
	subtitle = "The Deceiver",
	tier = "A",
	region = "kalimdor",
	allegiance = "Burning Legion",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Kil'jaeden the Deceiver is one of the great lords of the {link:burning-legion}Burning Legion{/link}, served only by the will of {link:sargeras}Sargeras{/link}. He was once a leader of the eredar with {link:archimonde}Archimonde{/link}, and he accepted the dark titan's offer as Archimonde did. He is a master of lies. It was Kil'jaeden who corrupted the orcs of {red:draenor}Draenor{/red}, and it was he who made the {red:lich-king}Lich King{/red}.]=],
		},
		{
			title = "Significance",
			text = [=[Few of the calamities of the last generation lack the Deceiver's hand. Through {link:ner-zhul}Ner'zhul{/link} and {link:gul-dan}Gul'dan{/link} he turned the orcs into a weapon. Through the Lich King he loosed the {link:scourge}Scourge{/link} on {link:lordaeron}Lordaeron{/link}. Unlike {link:archimonde}Archimonde{/link}, he has never been defeated.]=],
		},
		{
			title = "The Eredar",
			text = [=[Long ago, the eredar were ruled by three leaders: Kil'jaeden, {link:archimonde}Archimonde{/link} and Velen. {link:sargeras}Sargeras{/link} came to them with promises of knowledge and power. Kil'jaeden and Archimonde accepted, and they and their people were twisted into demons. Velen refused, and fled with his followers. Kil'jaeden hated him for it, and he swore to hunt Velen's people wherever they went.]=],
		},
		{
			title = "The Orcs",
			text = [=[Velen's people, the draenei, came at last to Draenor, where the orcs dwelt. Kil'jaeden found them there. He went to the old shaman {link:ner-zhul}Ner'zhul{/link} in the guise of a spirit of the ancestors, and he told him that the draenei plotted against his people. When Ner'zhul began to doubt him, the Deceiver turned to his apprentice, {link:gul-dan}Gul'dan{/link}, and taught him the arts of {link:fel-magic}fel magic{/link}. Through Gul'dan he gave the orcs the blood of {link:mannoroth}Mannoroth{/link}, bound them to the Legion, and set them upon the draenei.]=],
		},
		{
			title = "Deeds",
			text = [=[• He accepted {link:sargeras}Sargeras{/link}'s offer and became a lord of the Legion.
• He deceived {link:ner-zhul}Ner'zhul{/link} and turned the orcs against the draenei.
• He taught {link:gul-dan}Gul'dan{/link} the arts of fel magic.
• He made Ner'zhul into the Lich King.
• He sent the Lich King to prepare {link:azeroth}Azeroth{/link} for the Legion.]=],
		},
		{
			title = "The Lich King",
			text = [=[When {link:ner-zhul}Ner'zhul{/link} fled the ruin of Draenor, Kil'jaeden was waiting for him. He tore away the shaman's body and bound his spirit into armor and a helm. He sealed him in ice and cast him down upon {red:northrend}Northrend{/red}, commanding him to spread a plague that would weaken the world before the Legion came. The Lich King did so. When {link:archimonde}Archimonde{/link} fell at {link:mount-hyjal}Mount Hyjal{/link}, the Deceiver learned that his servant had begun to slip his chains.]=],
		},
		{
			title = "Fate",
			text = [=[Kil'jaeden has not set foot on {link:azeroth}Azeroth{/link}. After the {link:third-war}Third War{/link}, he sought to have the Lich King destroyed by others. The Lich King endures, and the Deceiver still watches from beyond the world.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The chronicles do not say where Kil'jaeden dwells, or what he plans now.]=],
